    startImport: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /** @description Workspace slug */
                slug: string;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                /**
                 * @example {
                 *       "source": "trello",
                 *       "api_key": "<key>",
                 *       "token": "<token>",
                 *       "boards": [
                 *         "5f1b…"
                 *       ],
                 *       "access": "RESTRICTED"
                 *     }
                 */
                "application/json": {
                    /** @constant */
                    source: "kanbn";
                    /** @description Your Kan instance (default https://kan.bn) */
                    base_url?: string;
                    /** @description A Kan API key (Settings → API) */
                    api_key: string;
                    /** @description Source board ids (kan.bn board publicId, Trello board id), at most 50 */
                    boards: string[];
                    /**
                     * @description Access of the new boards: RESTRICTED (default; the importer and matched people are members) or WORKSPACE
                     * @default RESTRICTED
                     * @enum {string}
                     */
                    access?: "RESTRICTED" | "WORKSPACE";
                    /** @description Source person → workspace member: `{ "<source person key>": "<user id>" | null }`. People not listed are matched automatically (email, then username, then a unique full name); null leaves them unassigned (their name is kept on their comments). */
                    people?: {
                        [key: string]: string | null;
                    };
                } | {
                    /** @constant */
                    source: "trello";
                    /** @description Trello API key */
                    api_key: string;
                    /** @description Trello token for that key */
                    token: string;
                    /** @description Source board ids (kan.bn board publicId, Trello board id), at most 50 */
                    boards: string[];
                    /**
                     * @description Access of the new boards: RESTRICTED (default; the importer and matched people are members) or WORKSPACE
                     * @default RESTRICTED
                     * @enum {string}
                     */
                    access?: "RESTRICTED" | "WORKSPACE";
                    /** @description Source person → workspace member: `{ "<source person key>": "<user id>" | null }`. People not listed are matched automatically (email, then username, then a unique full name); null leaves them unassigned (their name is kept on their comments). */
                    people?: {
                        [key: string]: string | null;
                    };
                } | {
                    /** @constant */
                    source: "trello_file";
                    /** @description A Trello board JSON export (Board menu → Print, export and share → Export as JSON) */
                    board: {
                        id: string;
                        lists: unknown[];
                        cards: unknown[];
                    } & {
                        [key: string]: unknown;
                    };
                    /**
                     * @description Access of the new boards: RESTRICTED (default; the importer and matched people are members) or WORKSPACE
                     * @default RESTRICTED
                     * @enum {string}
                     */
                    access?: "RESTRICTED" | "WORKSPACE";
                    /** @description Source person → workspace member: `{ "<source person key>": "<user id>" | null }`. People not listed are matched automatically (email, then username, then a unique full name); null leaves them unassigned (their name is kept on their comments). */
                    people?: {
                        [key: string]: string | null;
                    };
                };
            };
        };
        responses: {
            /** @description Accepted */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["StartImportResponse"];
                };
            };
            400: components["responses"]["BadRequest"];
            401: components["responses"]["Unauthorized"];
            403: components["responses"]["Forbidden"];
            404: components["responses"]["NotFound"];
            409: components["responses"]["Conflict"];
            422: components["responses"]["Invalid"];
            429: components["responses"]["TooManyRequests"];
        };
    };
